"workflow": {
  "title": "Museum Object Loan Workflow",
  "summary": "A museum processes loan requests for cultural objects between institutions, balancing preparation efficiency with conservation and accountability standards."
},
"evidence": [
  {"id": "ev-ai-drafts-summary", "quote": "An AI assistant reads the request, the catalogue entry and the conservation report, then drafts a suitability summary and a proposed checklist."},
  {"id": "ev-conservator-assess", "quote": "A conservator assesses the object's condition."},
  {"id": "ev-registrar-checks", "quote": "The registrar checks availability, insurance and transport arrangements."},
  {"id": "ev-committee-decision", "quote": "The lending committee makes the final loan decision."},
  {"id": "ev-ai-limits", "quote": "The assistant may prepare documents but cannot approve a loan, sign an agreement, publish an object's storage location or instruct a courier."},
  {"id": "ev-conservation-pending", "quote": "If conservation evidence is missing, the case stays pending until the conservator responds."},
  {"id": "ev-exhibition-conflict", "quote": "If the dates conflict with an existing exhibition, the registrar proposes alternatives."},
  {"id": "ev-handover-scheduling", "quote": "After approval, the registrar schedules the hand,over and records return-condition checks."},
  {"id": "ev-cancellation-reason", "quote": "A cancellation closes the request with a recorded reason."},
  {"id": "ev-storage-restriction", "quote": "Access to precise storage locations is restricted to authorised museum staff."}
],
"facts": [
  {"id": "fact-ai-assistant-role", "evidence_ids": ["ev-ai-drafts-summary", "ev-ai-limits"]},
  {"id": "fact-conservator-assessment", "evidence_ids": ["ev-conservator-assess"]},
  {"id": "fact-registrar-responsibilities", "evidence_ids": ["ev-registrar-checks", "ev-exhibition-conflict", "ev-handover-scheduling"]},
  {"id": "fact-committee-decision", "evidence_ids": ["ev-committee-decision"]},
  {"id": "fact-storage-access", "evidence_ids": ["ev-storage-restriction"]}
],
"assumptions": [
  {"id": "asm-catalogue-api", "statement": "No catalogue API is selected for integration", "rationale": "Source states: 'We have not selected a catalogue API'"},
  {"id": "asm-retention-periods", "statement": "Retention periods for records are undefined", "rationale": "Source states: 'We have not defined retention periods'"},
  {"id": "asm-exception-approvals", "statement": "No documented process for approving exceptions exists", "rationale": "Source states: 'We have not documented who may approve exceptions'"}
],
"actors": [
  {"id": "actor-curator", "label": "Curator", "kind": "human", "source_state": "stated", "evidence_ids": ["ev-ai-drafts-summary"]},
