  {"id": "step-ai-draft", "label": "AI Drafts Summary", "description": "AI creates suitability summary and checklist", "actor_ids": ["actor-ai-assistant"], "input_data_ids": ["data-loan-request", "data-conservation-report"], "output_data_ids": ["data-loan-request"], "tool_ids": ["tool-ai-assistant"], "source_state": "stated", "evidence_ids": ["ev-ai-drafts-summary"]},
  {"id": "step-conservator-assess", "label": "Conservator Assessment", "description": "Evaluates object condition", "actor_ids": ["actor-conservator"], "input_data_ids": ["data-conservation-report"], "output_data_ids": ["data-conservation-report"], "tool_ids": [], "source_state": "stated", "evidence_ids": ["ev-conservator-assess"]},
