  {"from_step_id": "step-registrar-checks", "to_step_id": "step-committee-decision", "condition": "All checks passed", "source_state": "stated", "evidence_ids": ["ev-registrar-checks"]},
  {"from_step_id": "step-committee-decision", "to_step_id": "step-handover-scheduling", "condition": "Loan approved", "source_state": "stated", "evidence_ids": ["ev-handover-scheduling"]},
