  {"id": "req-exception-approvals", "statement": "Document exception approval process", "kind": "unknown", "source_state": "stated", "evidence_ids": ["asm-exception-approvals"]}
],
"existing_controls": [
  {"id": "existing-control-ai-limits", "description": "AI assistant cannot approve loans or sign agreements", "step_ids": ["step-committee-decision"], "source_state": "stated", "evidence_ids": ["ev-ai-limits"]}
],
"risks": [
  {"id": "risk-ai-approval", "title": "AI Overstepping Authority", "scenario": "AI assistant approves loan without human oversight", "impact": "Unauthorized loan agreement", "step_ids": ["step-committee-decision"], "data_ids": ["data-loan-request"], "evidence_ids": ["ev-ai-limits"],"uncertainty": "AI's role is limited to drafting, but no explicit guardrails are described.","proposed_priority": "high"},
  {"id": "risk-conservation-gap", "title": "Incomplete Conservation Evidence", "scenario": "Loan approved without conservation report", "impact": "Object damage during transit", "step_ids": ["step-conservator-assess"], "data_ids": ["data-conservation-report"], "evidence_ids": ["ev-conservation-pending"],"uncertainty": "No explicit validation of conservation report completeness","proposed_priority": "medium"},
  {"id": "risk-exhibition-conflict", "title": "Exhibition Date Conflict", "scenario": "Loan scheduled during active exhibition", "impact": "Disruption of exhibition operations", "step_ids": ["step-registrar-checks"], "data_ids": ["data-loan-request"], "evidence_ids": ["ev-exhibition-conflict"],"uncertainty": "Registrar's alternatives are not quantified","proposed_priority": "medium"}
],
"controls": [
  {"id": "ctrl-ai-approval-guardrail", "family": "human_approval", "recommendation": "Implement explicit approval workflow for loan decisions", "enforcement_point": "step-committee-decision", "risk_ids": ["risk-ai-approval"], "step_ids": ["step-committee-decision"], "owner_actor_ids": ["actor-lending-committee"], "validation": "Test: Submit loan request without committee approval; expect denial or hold"},
  {"id": "ctrl-conservation-validation", "family": "data_quality", "recommendation": "Require complete conservation report before proceeding", "enforcement_point": "step-conservator-assess", "risk_ids": ["risk-conservation-gap"], "step_ids": ["step-conservator-assess"], "owner_actor_ids": ["actor-conservator"], "validation": "Test: Submit request with incomplete conservation report; expect pending status"},
  {"id": "ctrl-exhibition-alternatives", "family": "data_quality", "recommendation": "Mandate alternative date proposals for conflicting exhibitions", "enforcement_point": "step-registrar-checks", "risk_ids": ["risk-exhibition-conflict"], "step_ids": ["step-registrar-checks"], "owner_actor_ids": ["actor-registrar"], "validation": "Test: Submit request with exhibition conflict; expect alternative dates proposal"}
],
"gaps": [
